#include <WiFi.h>
#include <WiFiMulti.h>

WiFiMulti wifiMulti;
unsigned long lastPrintAt = 0;

void setup() {
  Serial.begin(115200);
  WiFi.mode(WIFI_STA);
  wifiMulti.addAP("YOUR_WIFI_1", "PASSWORD_1");
  wifiMulti.addAP("YOUR_WIFI_2", "PASSWORD_2");
}

void loop() {
  if (wifiMulti.run() == WL_CONNECTED &&
      millis() - lastPrintAt >= 5000) {
    lastPrintAt = millis();
    Serial.println(WiFi.localIP());
  }
  delay(10);
}

#include <WiFi.h>
#include <WebServer.h>

WebServer server(80);

void setup() {
  WiFi.mode(WIFI_AP);
  WiFi.softAP("Sensor-Setup", "change-this-pass");
  server.on("/", []() {
    server.send(200, "text/plain", "Sensor is ready");
  });
  server.begin();
}

void loop() {
  server.handleClient();
}
